// Initialize canvas and variables
const canvas = document.getElementById('map');
const ctx = canvas.getContext('2d');
canvas.width = 500;
canvas.height = 500;
const map = Array.from({length: 500}, () => new Array(500).fill(0));
const colors = {
  wall: '#000',
  floor: '#808080',
  start: '#008000',
  weapon: '#ff0000',
};
let startX, startY;

// Flood fill to check reachability
function floodFill(x, y) {
  if (x < 0 || x >= 500 || y < 0 || y >= 500) return;
  if (map[y][x] !== 0) return;
  map[y][x] = 1;
  floodFill(x + 1, y);
  floodFill(x - 1, y);
  floodFill(x, y + 1);
  floodFill(x, y - 1);
}

// Generate random room
function generateRoom(x, y, w, h) {
  for (let i = 0; i < w; i++) {
    for (let j = 0; j < h; j++) {
      map[y + i][x + j] = 0;
      floodFill(x + j, y + i);
    }
  }
}

// Generate corridor between rooms
function generateCorridor(x1, y1, x2, y2) {
  const dx = Math.abs(x2 - x1);
  const dy = Math.abs(y2 - y1);
  const sx = x1 < x2 ? 1 : -1;
  const sy = y1 < y2 ? 1 : -1;
  let x = x1;
  let y = y1;
  while (x !== x2 || y !== y2) {
    map[y][x] = 0;
    floodFill(x, y);
    x += sx;
    y += sy;
  }
}

// Generate procedural FPS map
function generateMap() {
  // Clear previous map
  for (let i = 0; i < 500; i++) {
    for (let j = 0; j < 500; j++) {
      map[i][j] = -1;
    }
  }
  // Place starting position
  while (true) {
    startX = Math.floor(Math.random() * 500);
    startY = Math.floor(Math.random() * 500);
    if (map[startY][startX] === 0) break;
  }
  map[startY][startX] = 2;
  // Generate rooms and corridors
  const num Rooms = Math.floor(Math.random() * 10) + 5;
  for (let i = 0; i < num Rooms; i++) {
    const x = Math.floor(Math.random() * 500);
    const y = Math.floor(Math.random() * 500);
    const w = Math.floor(Math.random() * 50) + 5;
    const h = Math.floor(Math.random() * 50) + 5;
    generateRoom(x, y, w, h);
    if (i === 0) {
      startX = x + Math.floor(w / 2);
      startY = y + Math.floor(h / 2);
    }
  }
  for (let i = 1; i < num Rooms; i++) {
    let x1 = 0;
    let y1 = 0;
    while (true) {
      x1 = Math.floor(Math.random() * 500);
      y1 = Math.floor(Math.random() * 500);
      if (map[y1][x1] === -1) {
        break;
      }
    }
    const x2 = startX;
    const y2 = startY;
    generateCorridor(x1, y1, x2, y2);
  }
  // Paint map
  for (let i = 0; i < 500; i++) {
    for (let j = 0; j < 500; j++) {
      ctx.fillStyle = colors[map[i][j]];
      ctx.fillRect(j * 10, i * 10, 10, 10);
    }
  }
  // Place weapon pickups
  for (let i = 0; i < Math.floor(Math.random() * 10) + 5; i++) {
    let x = 0;
    let y = 0;
    while (true) {
      x = Math.floor(Math.random() * 500);
      y = Math.floor(Math.random() * 500);
      if (map[y][x] === 1) {
        break;
      }
    }
    map[y][x] = 3;
    ctx.fillStyle = colors.weapon;
    ctx.fillRect(x * 10, y * 10, 10, 10);
  }
  // Clear screen
  ctx.fillStyle = '#fff';
